// Move with the joystick and face the walking direction.
export let speed = 5;   // meters per second, set per object in the Inspector

function update(dt) {
  const x = input.axis.x;
  const y = input.axis.y;
  entity.translate(x * speed * dt, 0, -y * speed * dt);
  if (x !== 0 || y !== 0) {
    entity.rotation.y = Math.atan2(-x, y) * 180 / Math.PI;
  }
}

// Jump when the "jump" button is pressed (needs a RigidBody).
export let jumpStrength = 7;

function update(dt) {
  if (input.wasPressed('jump') && entity.isOnGround()) {
    const v = entity.getVelocity();
    entity.setVelocity(v.x, jumpStrength, v.z);
  }
}

// Tap (or click) the ground: walk there, going around walls.
export let speed = 4;

function update(dt) {
  if (input.tapped) {
    const p = game.touchWorld();
    entity.moveTo(p.x, p.z, speed);
  }
}

