// Global script: ask a web server for data and send a score.
// Only https:// works. A game played from the gallery may only contact the domains you list in
// Project settings → Web requests → Allowed domains.
async function loadScores() {
  const r = await game.http.get('https://example.com/scores.json');
  if (!r.ok) { game.log('No scores: ' + r.error); return; }   // never throws: a failure is ok = false
  game.setVar('TopName', r.json.list[0].name);              // r.json is the reply read as JSON
}

async function sendScore() {
  // An object is sent as JSON. Never put a secret key in a game: call your own server instead.
  const r = await game.http.post('https://example.com/score', { name: 'Ann', score: game.getVar('Score') });
  if (!r.ok) game.log('Score not sent: ' + r.error);
}

loadScores();
game.on('died', sendScore);

// Global script: make a room, show its code, and share each player's position.
// One player runs create(); the others run join(code) with the code they were given.
// The room only relays messages (it never runs your game): everyone moves their own object and tells the others.
async function start() {
  const r = await game.net.create({ name: 'Player', max: 4 });
  if (!r.ok) { game.log('No room: ' + r.error); return; }   // never throws: "notfound", "full", "busy" or "offline"
  game.setVar('RoomCode', r.code);                         // show it in a Text, friends type it to join
}

