game.on('netPlayerJoined', (e) => game.log(e.player.name + ' joined'));
game.on('netPlayerLeft', (e) => game.log(e.player.name + ' left'));

// Receive: move the matching puppet (an object named after the player) to where they say they are.
game.on('netMessage', (m) => {
  if (m.name !== 'pos') return;
  const puppet = game.find(m.from.name);
  if (puppet) puppet.setPosition(m.data.x, m.data.y, m.data.z);
});

// Send my position about ten times a second (at most 30 messages a second are allowed).
let timer = 0;
function update(dt) {
  timer += dt;
  if (timer < 0.1 || game.net.state !== 'online') return;
  timer = 0;
  const me = game.find('Player');
  if (me) game.net.send('pos', { x: me.position.x, y: me.position.y, z: me.position.z });
}

start();

// Endless-runner style lane switching.
let lane = 0; // -1, 0, 1

function update(dt) {
  if (input.swipe === 'left') lane = clamp(lane - 1, -1, 1);
  if (input.swipe === 'right') lane = clamp(lane + 1, -1, 1);
  if (input.swipe === 'up' && entity.isOnGround()) entity.applyImpulse(0, 6, 0);
  entity.position.x = lerp(entity.position.x, lane * 2, 10 * dt);
}

// Put this on the Player. Give the vehicle the tag "vehicle" and a Car or Boat behavior, and add
// a control button called "use" in Scene → Controls.
function update(dt) {
  const vehicle = entity.vehicle;

  if (input.wasPressed('use')) {
    if (vehicle) {
      entity.exitVehicle();   // put down beside it, walking again, camera back on you
    } else {
      // Get in: the nearest vehicle within 3 meters.
      let nearest = null;
      for (const v of game.select('#vehicle')) {
        if (entity.distanceTo(v) < 3 && (!nearest || entity.distanceTo(v) < entity.distanceTo(nearest))) nearest = v;
      }
      if (nearest) entity.enterVehicle(nearest);   // sits in the seat, camera follows
    }
    return;
  }

  // Entering does not steer: pass the joystick to whoever you are driving.
  if (vehicle) {
    if (vehicle.behavior('car')) vehicle.driveCar(input.axis.x, Math.max(input.axis.y, 0), Math.max(-input.axis.y, 0));
    else vehicle.setMoveInput(input.axis.x, input.axis.y);
  } else {
    entity.setMoveInput(input.axis.x, input.axis.y);
  }
}

// Put this on an object with a Car (or Boat, or Platformer) behavior. The behavior does
// nothing until you tell it what to do; read the joystick and pass it in.
function update(dt) {
  const x = input.axis.x;   // left / right
  const y = input.axis.y;   // up / down

  // Car: steer, gas, brake
  entity.driveCar(x, Math.max(y, 0), Math.max(-y, 0));

